  app.post('/api/site-forms/integrations',auth,requirePermission(deps,'manage_site_form_integrations'),async(req,res)=>{try{const v=normalizeIntegrationInput(req.body),id=crypto.randomUUID(),plain=generateWebhookToken();await queryPBXPulsDb(`INSERT INTO site_form_integrations(id,name,provider,site_id,site_url,webhook_token_hash,is_enabled,allowed_ips_json,allowed_form_ids_json,default_user_id,default_department_id,sla_minutes,duplicate_detection_enabled,duplicate_window_minutes,call_match_window_days,minimum_answered_seconds)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,[id,v.name,v.provider,v.siteId,v.siteUrl,hashWebhookToken(id,plain,deps.secret),v.isEnabled?1:0,JSON.stringify(v.allowedIps),JSON.stringify(v.allowedFormIds),v.defaultUserId,v.defaultDepartmentId,v.slaMinutes,v.duplicateDetectionEnabled?1:0,v.duplicateWindowMinutes,v.callMatchWindowDays,v.minimumAnsweredSeconds]);await writePBXPulsAuditLog({actor_label:actor(req).label,action:'site_forms.integration.created',entity_type:'site_form_integration',entity_id:id,details:{provider:v.provider,siteUrl:v.siteUrl},ip_address:req.ip,user_agent:req.get('user-agent')});res.status(201).json({success:true,integrationId:id,webhookToken:plain,webhookUrl:`/api/integrations/site-forms/${id}/webhook`,tokenShownOnce:true})}catch(e:any){const x=e instanceof SiteFormError?e:new SiteFormError(500,'internal_error','Не удалось создать интеграцию');res.status(x.status).json({error:x.message,code:x.code})}});
